package bookstore

// Cost returns the total cost, in cents, of the books in the basket,
// after applying the shop's discounts and grouping the books to get
// the biggest possible discount.
func Cost(books []int) int {
	var counts [5]int
	for _, book := range books {
		counts[book-1]++
	}
	return minCost(counts, make(map[[5]int]int))
}

// price[size] is the cost, in cents, of a group of `size` distinct books.
// 1 book: no discount, 2: 5%, 3: 10%, 4: 20%, 5: 25%.
var price = [6]int{0, 800, 1520, 2160, 2560, 3000}

// minCost computes the minimum cost of buying the given multiset of books
// by trying every possible first group (a set of distinct titles) and
// memoizing the result.
func minCost(counts [5]int, memo map[[5]int]int) int {
	if counts == ([5]int{}) {
		return 0
	}
	if v, ok := memo[counts]; ok {
		return v
	}
	best := -1
	for mask := 1; mask < 32; mask++ {
		size := 0
		ok := true
		for i := 0; i < 5; i++ {
			if mask&(1<<i) != 0 {
				if counts[i] == 0 {
					ok = false
					break
				}
				size++
			}
		}
		if !ok {
			continue
		}
		next := counts
		for i := 0; i < 5; i++ {
			if mask&(1<<i) != 0 {
				next[i]--
			}
		}
		cost := price[size] + minCost(next, memo)
		if best < 0 || cost < best {
			best = cost
		}
	}
	memo[counts] = best
	return best
}
```

